#!/usr/bin/env python3
"""Keep a generated badge block at the top of every repository's README.

Each README carries one block between markers, directly under its title:

    <!-- badges:start - generated by traction-control scripts/readme_badges.py ... -->
    [![CI](...)](...) [![License: MIT](...)](LICENSE) [![Python 3.10+](...)](pyproject.toml)
    <!-- badges:end -->

The block is built from facts about the repository, so a repository only shows a badge it
can honestly show:

- **CI**: GitHub's own workflow badge, when ``.github/workflows/ci.yml`` exists. GitHub serves
  these itself with the viewer's session, so they also work in private repositories.
- **License**: the SPDX id GitHub detects, as a static badge; none when GitHub cannot tell.
- **Python**: the floor from ``requires-python`` (``>=3.10`` becomes ``3.10+``), static.
- **Coverage**: Codecov, when ``ci.yml`` turns on ``coverage``. A private repository's badge
  needs Codecov's graph token (a read-only badge token) in its URL, which ``apply`` fetches
  with the Codecov PAT in the vault; the audit compares the block with that token masked.

Commands:

- ``render --repo NAME``: print the block for a repository.
- ``check (--repo NAME ... | --all)``: compare each README on GitHub with the block it should
  have; exit 1 if any differs. ``--all`` uses the visibility registry. The daily portfolio
  audit runs it.
- ``apply --repo NAME --readme PATH``: write the block into a local README (``--dry-run`` shows
  the result instead). Badges written by hand outside the block are left alone and listed, so
  duplicates can be folded in by hand.
"""

from __future__ import annotations

import argparse
import base64
import re
import sys
import urllib.parse
from collections.abc import Sequence
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import actions_switch as sw  # noqa: E402
import codecov_secrets as cs  # noqa: E402

START = (
    "<!-- badges:start - generated by traction-control scripts/readme_badges.py; "
    "change the repository's facts, not this block -->"
)
END = "<!-- badges:end -->"
BLOCK_RE = re.compile(re.escape(START.split(" - ")[0]) + r".*?" + re.escape(END) + r"\n?", re.S)
TOKEN_RE = re.compile(r"token=[^)&\s]+")
GRAPH_TOKEN_MASK = "<graph-token>"
HAND_BADGE_RE = re.compile(
    r"!\[[^\]]*\]\(https?://(?:img\.shields\.io|badge\.fury\.io|codecov\.io|github\.com/[^)\s]*badge\.svg)[^)]*\)"
)
LICENSE_FILE_RE = re.compile(r"^(LICENSE|LICENCE|COPYING)(\.[A-Za-z]+)?$", re.I)
UNKNOWN_LICENSES = {None, "", "NOASSERTION", "none"}
OWNER = "casonk"


class BadgeError(Exception):
    """A failure to report in a sentence, not a traceback."""


@dataclass(frozen=True)
class Facts:
    slug: str
    branch: str
    private: bool
    license_id: str | None = None
    license_file: str | None = None
    ci: bool = False
    python_floor: tuple[int, int] | None = None
    coverage: bool = False
    archived: bool = False  # read-only on GitHub: nothing can be changed, so nothing is checked


def python_floor(requires: str | None) -> tuple[int, int] | None:
    """``>=3.10`` or ``>=3.9,<4`` gives (3, 10) or (3, 9); anything else gives None."""
    match = re.search(r">=\s*(\d+)\.(\d+)", requires or "")
    return (int(match.group(1)), int(match.group(2))) if match else None


def static_text(text: str) -> str:
    """Escape text for the path of a shields.io static badge (``-`` and ``_`` are doubled)."""
    escaped = text.replace("-", "--").replace("_", "__").replace(" ", "_")
    return urllib.parse.quote(escaped, safe="-_")


def badges(facts: Facts, graph_token: str | None = None) -> list[str]:
    out = []
    repo = facts.slug
    if facts.ci:
        workflow = f"https://github.com/{repo}/actions/workflows/ci.yml"
        out.append(f"[![CI]({workflow}/badge.svg?branch={facts.branch})]({workflow})")
    if facts.license_id not in UNKNOWN_LICENSES:
        target = facts.license_file or "LICENSE"
        label = static_text(str(facts.license_id))
        out.append(f"[![License: {facts.license_id}](https://img.shields.io/badge/license-{label}-blue)]({target})")
    if facts.python_floor:
        text = f"{facts.python_floor[0]}.{facts.python_floor[1]}+"
        out.append(f"[![Python {text}](https://img.shields.io/badge/python-{urllib.parse.quote(text)}-blue)](pyproject.toml)")
    if facts.coverage:
        url = f"https://codecov.io/gh/{repo}/graph/badge.svg"
        if facts.private:
            url += f"?token={graph_token or GRAPH_TOKEN_MASK}"
        out.append(f"[![Coverage]({url})](https://codecov.io/gh/{repo})")
    return out


def block(facts: Facts, graph_token: str | None = None) -> str:
    """The managed block, or an empty string when there is nothing to show."""
    items = badges(facts, graph_token)
    return f"{START}\n{' '.join(items)}\n{END}\n" if items else ""


def mask(text: str) -> str:
    return TOKEN_RE.sub(f"token={GRAPH_TOKEN_MASK}", text)


def strip_block(readme: str) -> str:
    return BLOCK_RE.sub("", readme, count=1)


def apply_block(readme: str, new_block: str) -> str:
    """Replace the managed block, or insert it under the first title; remove it if empty."""
    had_block = BLOCK_RE.search(readme) is not None
    if had_block and new_block:
        return BLOCK_RE.sub(lambda _m: new_block, readme, count=1)
    body = strip_block(readme)
    if had_block:  # tidy the blank line the block leaves behind
        body = re.sub(r"\n{3,}", "\n\n", body)
    if not new_block:
        return body
    lines = body.splitlines()
    title = next((i for i, line in enumerate(lines) if line.strip()), None)
    if title is None or not lines[title].startswith("# "):
        raise BadgeError("the README does not start with a '# ' title")
    rest = lines[title + 1 :]
    while rest and not rest[0].strip():
        rest.pop(0)
    head = lines[: title + 1]
    pieces = [*head, "", *new_block.rstrip("\n").splitlines(), ""]
    if rest:
        pieces.extend(rest)
    return "\n".join(pieces).rstrip("\n") + "\n"


def hand_made_badges(readme: str) -> list[str]:
    return HAND_BADGE_RE.findall(strip_block(readme))


# --- facts from GitHub --------------------------------------------------------


def _text(github: sw.GitHub, path: str) -> str | None:
    try:
        content = (github.api("GET", path) or {}).get("content")
    except sw.GitHubError:
        return None
    return base64.b64decode(content).decode("utf-8", "replace") if content else None


def gather(slug: str, github: sw.GitHub) -> tuple[Facts, str | None]:
    """Facts about a repository's default branch, and its README text."""
    info = github.api("GET", f"repos/{slug}")
    branch = info["default_branch"]
    tree = github.api("GET", f"repos/{slug}/git/trees/{branch}?recursive=1") or {}
    paths = [item["path"] for item in tree.get("tree", [])]
    license_file = next((p for p in paths if "/" not in p and LICENSE_FILE_RE.match(p)), None)
    pyproject = _text(github, f"repos/{slug}/contents/pyproject.toml") if "pyproject.toml" in paths else None
    requires = re.search(r'^requires-python\s*=\s*"([^"]*)"', pyproject or "", re.M)
    ci = ".github/workflows/ci.yml" in paths
    workflow = _text(github, f"repos/{slug}/contents/.github/workflows/ci.yml") if ci else None
    facts = Facts(
        slug=slug,
        branch=branch,
        private=bool(info.get("private")),
        license_id=(info.get("license") or {}).get("spdx_id"),
        license_file=license_file,
        ci=ci,
        python_floor=python_floor(requires.group(1) if requires else None),
        coverage=bool(re.search(r"^\s*coverage:\s*true\b", workflow or "", re.M)),
        archived=bool(info.get("archived")),
    )
    return facts, _text(github, f"repos/{slug}/contents/README.md")


# --- checking -----------------------------------------------------------------


def judge(facts: Facts, readme: str | None) -> tuple[str, str]:
    """(status, detail): status is ``ok``, ``archived`` or what is wrong."""
    if facts.archived:
        return "archived", "read-only on GitHub"
    if readme is None:
        return "no-readme", "README.md not found"
    expected = block(facts)
    found = BLOCK_RE.search(readme)
    if not expected:
        return ("stale", "has a badge block but no badge applies") if found else ("ok", "")
    if not found:
        return "missing", "no badge block"
    if mask(found.group(0)) != expected:
        return "drifted", "the block differs from what the repository's facts produce"
    return "ok", ""


def check(slugs: Sequence[str], github: sw.GitHub) -> list[tuple[str, str, str]]:
    def one(slug: str) -> tuple[str, str, str]:
        try:
            facts, readme = gather(slug, github)
            status, detail = judge(facts, readme)
        except (sw.GitHubError, KeyError) as exc:
            return slug, "error", str(exc)
        return slug, status, detail

    with ThreadPoolExecutor(max_workers=8) as pool:
        return list(pool.map(one, slugs))


def graph_token(slug: str, run: cs.Runner = cs.default_runner, http: cs.Http = cs.default_http) -> str:
    """Codecov's graph (badge-only) token for a repository, using the PAT in the vault."""
    pat = cs.read_pat(run)
    if pat.token is None:
        raise BadgeError(f"cannot read the Codecov PAT ({pat.state}): {pat.detail}")
    owner, _, name = slug.partition("/")
    status, body = cs.codecov_get(owner, name, "config/", pat.token, http)
    token = body.get("graph_token") if status == 200 and isinstance(body, dict) else None
    if not isinstance(token, str) or not cs.TOKEN_SHAPE.fullmatch(token):
        raise BadgeError(f"no graph token for {slug}: {cs.explain(status)}")
    return token


# --- command line -------------------------------------------------------------


def _slug(name: str) -> str:
    return name if "/" in name else f"{OWNER}/{name}"


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--private", type=Path, default=sw.REGISTRY_DIR / "private.local.json")
    parser.add_argument("--public", type=Path, default=sw.REGISTRY_DIR / "public.local.json")
    parser.add_argument("--local-private", type=Path, default=sw.REGISTRY_DIR / "local-private.local.json")
    parser.add_argument("--gh", default="gh", help="GitHub CLI executable.")
    sub = parser.add_subparsers(dest="command", required=True)
    render = sub.add_parser("render", help="Print the block for a repository.")
    render.add_argument("--repo", required=True, metavar="NAME")
    chk = sub.add_parser("check", help="Compare each README on GitHub with what it should have.")
    chk.add_argument("--repo", action="append", default=[], metavar="NAME")
    chk.add_argument("--all", action="store_true", help="Every repository in the visibility registry.")
    apply = sub.add_parser("apply", help="Write the block into a local README.")
    apply.add_argument("--repo", required=True, metavar="NAME")
    apply.add_argument("--readme", required=True, type=Path)
    apply.add_argument("--dry-run", action="store_true")
    return parser


def main(argv: Sequence[str] | None = None, github: sw.GitHub | None = None) -> int:
    args = _parser().parse_args(argv)
    github = github or sw.GitHub(args.gh)
    try:
        if args.command == "render":
            facts, _ = gather(_slug(args.repo), github)
            print(block(facts).rstrip("\n") or "(no badge applies)")
            return 0
        if args.command == "check":
            if args.all == bool(args.repo):
                raise BadgeError("give --all or at least one --repo")
            if args.all:
                local = args.local_private if args.local_private.exists() else None
                slugs, _ = sw.registry_slugs(args.private, args.public, local)
            else:
                slugs = [_slug(name) for name in args.repo]
            results = check(slugs, github)
            bad = [r for r in results if r[1] not in ("ok", "archived")]
            for slug, status, detail in bad:
                print(f"{slug}: {status}" + (f": {detail}" if detail else ""))
            print(f"{len(results)} repositories checked, {len(bad)} need attention")
            return 1 if bad else 0
        slug = _slug(args.repo)
        facts, _ = gather(slug, github)
        text = args.readme.read_text(encoding="utf-8")
        token = graph_token(slug) if facts.private and facts.coverage else None
        updated = apply_block(text, block(facts, token))
        extras = hand_made_badges(updated)
        if args.dry_run:
            print(updated)
        elif updated != text:
            args.readme.write_text(updated, encoding="utf-8")
        print(f"{slug}: {'unchanged' if updated == text else 'would change' if args.dry_run else 'updated'}", file=sys.stderr)
        for badge in extras:
            print(f"note: badge written by hand outside the block: {badge}", file=sys.stderr)
        return 0
    except (BadgeError, sw.SwitchError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
